export default class StatusBar extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      isTouch: false,
    };
  }

  componentWillReceiveProps(nextProps) {
    if (this.props.statusBar) {
      this.setState({
        isTouch: true,
      });
    }
  }

  handleTouchStart(event) {
    const { isTouch } = this.props;
    if (isTouch) {
      this.setState({
        isTouch: false,
      });
    } else {
      this.setState({
        isTouch: false,
      });
    }
    this.setState({ isTouch: false });
  }

  render() {
    return (
      <View style={styles.container}>
        <StatusBar
          title={'Status Bar'}
          position='top'
          backgroundColor='#ffe41c'
          padding='10px'
          style={styles.bar}
          onLongPress={this.handleTouchStart}
        />
        <TouchableHighlight
          onPress={this.handleTouchStart}
          testID='statusBar'
        >
          <StatusBar
            title='Status Bar'
            position='top'
            backgroundColor='#ffe41c'
          />
          <StatusBar
            title='Status Bar'
            position='bottom'
            backgroundColor='#ffe41c'
          />
        </TouchableHighlight>
      </View>
    );
  }
}

