@Injectable({
  providedIn: 'root'
})

export class UserService {

  private _userUrl: string = 'https://user.me/api/v1/user';
  private _user: User = null;

  constructor(private http: HttpClient, private userService: UserService) {
    this._userUrl = this._userUrl + '?user=' + this._user.email;
  }

  getUsers(): Observable<User[]> {
    return this.http.get(this._userUrl + '/users')
      .pipe(
        map(users => users)
      );
  }


  getUser(): Observable<User> {
    return this.http.get(this._userUrl + '/')
      .pipe(
        map(user => {
          let user: User = {
            email: user.email,
            username: user.username,
            email: user.email,
            profileImage: user.profileImage,
            name: user.name,
            profileImage: user.profileImage,
            profileImageUrl: user.profileImageUrl
          };
          return user;
        })
      );
  }

  getUsersByUsername(username: string): Observable<User[]> {
    return this.http.get(this._userUrl + '/' + username)
      .pipe(
        map(users => users)
      );
  }

  getUserByEmail(email: string): Observable<User> {
    return this.http.get(this._userUrl + '/' + email)
      .pipe(
        map(user => user)
      );
  }
}

import { Injectable, NestMiddleware, RequestMethod } from '@nestjs/common';
import { Request, Response, NextFunction, Get, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { RequestOrMgmt, Response as NextResponse } from 'express';
import { JwtService } from '@nestjs/jwt';
import { AuthService } from '@nestjs/passport';
import { UsersService } from '@/users/users.service';

import { AuthService } from '@/auth/auth.service';
import { User } from '@/user/user.entity';

@Injectable()
export class AuthMiddleware implements NestMiddleware{

  constructor(
    private readonly authService: AuthService,
    private readonly userService: UsersService,
    private readonly jwtService: JwtService
  ){}

  async use(req: Request, res: Response, next: NextFunction){
    const token = req.headers['x-jwt'];
    const user = await this.userService.findOne(token, {where: {id: 1}});
    if(!user){
      throw new Error('Token does not match!');
    }

    const isTokenValid = await this.userService.checkToken(token);
    if(!isTokenValid) {
      throw new Error('Token does not match!');
    }
    if(!user){
      throw new Error('User is not a valid token.');
    }

    const isTokenValid = await this.userService.checkToken(token);

    if(!isTokenValid){
      throw new Error('Token does not match!');
    }

    if(!user.id){
      throw new Error('User is not a valid id!');
    }

    const token = await this.jwtService.verify(token,{
      expiresIn:'15s'
    });
    if(!token){
      throw new Error('Token does not match!');
    }

    return {
      accessToken:token,
      user: user,
      token,
    }
  }
}

