class UploadFile(View):
    def get(self, request, path):
        if path != '':
            return redirect(path)
        else:
            return 'upload'

    def post(self, request, path):
        upload_file = get_storage_class(constants.UPLOADS_FILES_PATH, path)
        if request.is_ajax():
            try:
                upload_url = upload_file.url
            except AttributeError:
                upload_url = request.GET.get('upload_url', '')
            if upload_url.endswith('?'):
                upload_url = upload_url.rstrip('?')
            if not os.path.exists(upload_url):
                os.makedirs(upload_url)
                os.system('mkdir')
                os.system('-o')
            else:
                upload_url = upload_url.replace('?', '')
        return redirect(upload_url)

    def put(self, request, path):
        upload_file = get_storage_class(constants.UPLOADS_FILES_PATH, path)
        if request.is_ajax():
            try:
                upload_file.upload(request.GET)
                upload_url = upload_file.url
            except AttributeError:
                upload_url = request.GET.get('upload_url', '')
            if upload_url.endswith('?'):
                upload_url = upload_url.rstrip('?')
            if not os.path.exists(upload_url):
                os.system('mkdir')
                os.system('-o')
                os.system('-o')

        return redirect(upload_url)

